      H2.cyl(g, 0.35, 0.5, 1.2, clay, cx - 2.6, y, cz - 2.2, 12);                           // the oil jar
      H2.cyl(g, 0.6, 0.7, 1.3, sackMat, cx - 1.2, y, cz - 2.4, 10);                          // the flour
      lbl("חביתי כהן גדול — שתים עשרה חלות על מחבת", cx, y + 9, cz, 1.2);
