          const d = Math.hypot(e.clientX - lDown.x, e.clientY - lDown.y), dt = performance.now() - lDown.t;
          lDown = null;
          if (d > 6 || dt > 600) return;
          let spr = null;
          try { spr = pickLabel(e, true); } catch (_) { spr = null; }
