        hd.className = "hd";
        const nm = document.createElement("span");
        nm.textContent = label;
        hd.appendChild(nm);
        const src = document.createElement("a");
        src.textContent = "פתח את המקור";
        src.title = "פתיחת " + label + " באוצריא";
        src.addEventListener("click", (ev) => RD.open(ev, label, { book: L.book, index: L.index }));
